-- Handbook visibility boundary: post-kickoff messages arrive through Stage mutations.
DELETE FROM attachments
WHERE message_id IN (SELECT id FROM messages WHERE date > '2026-07-06T09:00:00+08:00');
DELETE FROM sent_log
WHERE message_id IN (SELECT id FROM messages WHERE date > '2026-07-06T09:00:00+08:00');
